import { _decorator, assetManager, AssetManager, Component, director, native, Scene, settings, SettingsCategory, sys } from 'cc';
import { PREVIEW } from 'cc/env';

const { ccclass, property } = _decorator;

// 預覽資料夾裡的遊戲頁找殼頁的位置 third-game/preview/<遊戲ID>/index.html 對 third-game/shell.html
const SHELL_PAGE = '../../shell.html';

type SlotGameScope = typeof globalThis & {
    __APP_GAME_ID__?: string;
};

/**
 * slot_game 的獨立測試入口。
 *
 * Editor：直接按執行時載入本專案 Bundle。
 * Web 構建：從同一份構建輸出的 remote/<gameId> 載入。
 * URL 可用 ?gameId=1002 或 ?gameId=1002&scene=1002 覆寫。
 * 沒有指定時 構建只帶一個遠端遊戲就用它 其餘才用預設值。
 * 直接開網頁版時 最外層沒有殼頁就去找殼頁並跳過去 讓選單與遊戲說明有地方彈。
 * entry 正式載入子遊戲時不會經過這個 Component。
 */
@ccclass('SlotGameLauncher')
export class SlotGameLauncher extends Component {
    @property({ tooltip: '沒有指定 ?gameId= 而且構建沒有單一遠端遊戲時（例如編輯器預覽），slot_game 獨立測試預設載入的遊戲' })
    public defaultGameId = '1001';

    /**
     * 最外層沒有殼頁或大廳時 找殼頁並跳過去 殼頁才有選單 自動旋轉 選座與遊戲說明可以彈
     *
     * 在編輯器 原生 殼頁或大廳的 iframe 裡不處理 找不到殼頁就留在原頁 網址加 shell=0 也不跳
     *
     * @param gameId 遊戲代號 殼頁用它找遊戲說明。
     * @returns 已經跳轉時為 true。
     */
    private async wrapInShell(gameId: string): Promise<boolean> {
        if (PREVIEW || sys.isNative || typeof window === 'undefined' || window.parent !== window) return false;
        if (new URLSearchParams(location.search).get('shell') === '0') return false;
        const shellUrl = new URL(SHELL_PAGE, location.href);
        try {
            const res = await fetch(shellUrl.href, { method: 'HEAD' });
            if (!res.ok) return false;
        } catch {
            return false;
        }
        shellUrl.searchParams.set('url', location.href);
        shellUrl.searchParams.set('gameId', gameId);
        location.replace(shellUrl.href);
        return true;
    }

    /**
     * 這份構建帶的遠端遊戲代號
     *
     * @returns 構建只含一個遠端遊戲時回傳它 沒有或多個回傳空字串。
     */
    private buildGameId(): string {
        const remote = settings.querySettings<string[]>(SettingsCategory.ASSETS, 'remoteBundles') ?? [];
        const games = Array.from(new Set(remote.filter((name) => /^\d+$/.test(name))));
        return games.length === 1 ? games[0] : '';
    }

    protected override async start(): Promise<void> {
        // 原生熱更新完成 game.restart() 重啟後 回到這個獨立測試入口
        // 沒有還原下載到的 searchPaths 就會抓不到剛更新的內容 又跑回內建舊版
        if (sys.isNative) {
            const raw = sys.localStorage.getItem('native_bundle_update_search_paths');
            if (raw) {
                try {
                    native.fileUtils.setSearchPaths(JSON.parse(raw) as string[]);
                } catch (err) {
                    console.warn('[SlotGameLauncher] 還原原生熱更新搜尋路徑失敗', err);
                }
            }
        }

        const params = new URLSearchParams(globalThis.location?.search ?? '');
        const gameId = params.get('gameId')?.trim() || this.buildGameId() || this.defaultGameId;
        const sceneName = params.get('scene')?.trim() || gameId;

        if (await this.wrapInShell(gameId)) return;

        (globalThis as SlotGameScope).__APP_GAME_ID__ = gameId;
        console.info(`[SlotGameLauncher] loading gameId=${gameId}, scene=${sceneName}`);

        try {
            const source = PREVIEW || sys.isNative ? gameId : `./remote/${gameId}`;
            const bundle = await new Promise<AssetManager.Bundle>((resolve, reject) => {
                assetManager.loadBundle(source, (err, loaded) => {
                    if (err) reject(err);
                    else resolve(loaded);
                });
            });
            const scene = await new Promise<Scene>((resolve, reject) => {
                bundle.loadScene(sceneName, (err, loaded) => {
                    if (err) reject(err);
                    else if (!loaded?.scene) reject(new Error(`scene "${sceneName}" was not returned`));
                    else resolve(loaded.scene);
                });
            });
            director.runScene(scene);
        } catch (err) {
            console.error(`[SlotGameLauncher] failed to load ${gameId}`, err);
        }
    }
}
